------------------------------------------------------------------------------------------------------ 











* K:\SAS\FMTLIB\ECHO.FMT;
* First missing value codes are recoded;
* FORMAT STATEMENTS FOR ECHO FORM;
* THESE ARE FORMAT STATEMENTS FOR VARIABLES IN ECHODATA.SSD; 
ARRAY NEGCODES ECCMMREQ ECDOREQ ECHGB MMSM MMPEF MMSM--MMARD
ECMMINT DORR--DOTRPV ECIRPT QCREVIEW RESOLVED;
DO OVER NEGCODES;
IF NEGCODES EQ -9 THEN NEGCODES=.;
IF NEGCODES EQ -1 THEN NEGCODES=.A;
IF NEGCODES EQ -8 THEN NEGCODES=.B;
IF NEGCODES EQ -7 THEN NEGCODES=.C;
END; 
ARRAY NEGDATES ECMMDATE ECDODATE ECHGBD 
ADD_DATE;
DO OVER NEGDATES;
IF NEGDATES EQ MDY(9,9,9) THEN NEGDATES=.;
IF NEGDATES EQ MDY(1,1,1) THEN NEGDATES=.A;
IF NEGDATES EQ MDY(8,8,8) THEN NEGDATES=.B;
IF NEGDATES EQ MDY(11,11,11) THEN NEGDATES=.C;
END; 
ARRAY TEXTNEGS ECMMREQM ECMMREQS ECMMRSN
ECDOREQM ECDOREQS ECDORSN
ECMMQUAL ECMMDX1 ECMMDX2 ECMMDX3 ECMMDX4
ECMMCOM ECDOQUAL ECDODX1 ECDODX2
ECDODX3 ECDODX4 ECDOCOMM;
DO OVER TEXTNEGS;
IF TEXTNEGS EQ '-1' THEN TEXTNEGS='MISSING, REASON';
IF TEXTNEGS EQ '-7' THEN TEXTNEGS='N/A';
IF TEXTNEGS EQ '-9' THEN TEXTNEGS='MISSING';
END; 
PROC FORMAT; 
* FORMAT NOYES is defined for variable ECMMREQ ECDOREQ
MMPEF ECIRPT RESOLVED; 
VALUE NOYES 
1 ='1-NO' 
2 ='2-YES' 
. ='MISSING' 
.A ='MISSING,REASON'
.B ='OUT-OF-RANGE' 
.C ='NOT APPLICABLE'; 
* FORMAT MOTION is defined for variable septal motion MMSM; 
VALUE MOTION 1='1-NORMAL' 
2='2-FLAT' 
3='3-PARADOXICAL' 
.='MISSING' 
.A='MISSING,REASON'
.B='OUT-OF-RANGE' 
.C='NOT APPLICABLE'; 
* FORMAT NORMABN is defined for variable ECMMINT; 
VALUE NORMABN 1='1-NORMAL' 
2='2-ABNORMAL' 
.='MISSING' 
.A='MISSING,REASON'
.B='OUT-OF-RANGE' 
